const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;},views=new Map();
const copy={en:{film:'THE FILM / SAME MOMENT',evidence:'Evidence through',observed:'What we can see',missing:'What the camera cannot tell us',beginner:'New to football',math:'Show the math',analyst:'Tactical view',replay:'Return to the discussion ↗',challenge:'Apply editorial challenge',restore:'Restore original reading',question:'Does a convincing image prove the claim?',claim:'“We can calculate the player’s speed from this footage.”',verdict:'WITHHOLD THE MEASUREMENT',reason:'Video time is known. Real-world travel distance is not calibrated. A number here would look authoritative without being supported.',after:'The observation survives. The speed claim does not.',before:'A realistic image deserves a careful explanation.',export:'Export this evidence ↓',source:'Reviewed observations from this exact generated film. No imported match statistics.'},es:{film:'EL VÍDEO / MISMO MOMENTO',evidence:'Evidencia hasta',observed:'Lo que podemos ver',missing:'Lo que la cámara no puede decir',beginner:'Empieza a entender',math:'Las matemáticas',analyst:'Visión táctica',replay:'Volver a la conversación ↗',challenge:'Aplicar revisión editorial',restore:'Restaurar lectura original',question:'¿Una imagen convincente demuestra la afirmación?',claim:'«Podemos calcular la velocidad del jugador con este vídeo».',verdict:'NO PUBLICAR LA MEDICIÓN',reason:'Conocemos el tiempo del vídeo. La distancia real no está calibrada. Una cifra parecería fiable sin estar respaldada.',after:'La observación se mantiene. La velocidad no.',before:'Una imagen realista merece una explicación rigurosa.',export:'Exportar evidencia ↓',source:'Observaciones revisadas de este vídeo generado. Sin estadísticas de otro partido.'},pt:{film:'O VÍDEO / MESMO MOMENTO',evidence:'Evidência até',observed:'O que podemos ver',missing:'O que a câmera não pode dizer',beginner:'Comece a entender',math:'Veja a matemática',analyst:'Visão tática',replay:'Voltar à conversa ↗',challenge:'Aplicar revisão editorial',restore:'Restaurar leitura original',question:'Uma imagem convincente comprova a afirmação?',claim:'“Podemos calcular a velocidade do jogador neste vídeo.”',verdict:'NÃO PUBLICAR A MEDIÇÃO',reason:'Conhecemos o tempo do vídeo. A distância real não está calibrada. Um número pareceria confiável sem ter fundamento.',after:'A observação permanece. A velocidade não.',before:'Uma imagem realista merece uma explicação cuidadosa.',export:'Exportar evidência ↓',source:'Observações revisadas deste vídeo gerado. Sem estatísticas de outra partida.'}};
function download(data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=el('a');a.href=url;a.download='btr-current-film-evidence.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function input(s){return {time:s.clipTime,language:s.language,mode:s.mode,clipChallenge:s.clipChallenge};}
function back(){document.getElementById('watch-nav').click();}
for(const section of ['centre','truth','inside']){
 const root=document.getElementById(section),legacy=el('div','synthetic-workspace');for(const child of [...root.children])if(!child.classList.contains('extension-heading'))legacy.append(child);root.append(legacy);
 const view=el('div','film-workspace');root.append(view);views.set(section,{view,legacy});
 if(section==='inside')continue;
 view.innerHTML='<div class="film-study-grid"><div class="film-study-screen"><div class="study-label"><strong></strong><time></time></div><video muted playsinline preload="metadata" controls></video><div class="study-caption"><span class="eyebrow"></span><h2></h2><p></p></div></div><aside class="film-study-evidence"><span class="eyebrow"></span><h3></h3><div class="film-evidence-list"></div></aside></div><div class="film-study-bottom"></div>';
 const video=view.querySelector('video');video.src=PITCHSIDE.asset;video.poster=PITCHSIDE.poster;video.addEventListener('loadedmetadata',()=>{video.currentTime=matchSession.get().clipTime;});video.setAttribute('aria-label','Same film and shared playhead');video.addEventListener('timeupdate',()=>{if(!video.paused&&matchSession.get().section===section)matchSession.set({clipTime:Math.min(PITCHSIDE.duration,video.currentTime)},'study-video');});video.addEventListener('seeked',()=>{if(matchSession.get().section===section&&Math.abs(video.currentTime-matchSession.get().clipTime)>.2)matchSession.set({clipTime:video.currentTime},'study-video');});
 const button=el('button','outline-button');button.onclick=back;view.querySelector('.film-study-evidence').append(button);
}
const inside=views.get('inside').view;
inside.innerHTML='<div class="film-production-head"><div><span class="eyebrow">THE WORKING PIPELINE</span><h2>One evidence record.<br>Every screen.</h2><p>Watch, review, personalize and publish from the same film and playhead.</p></div><button class="red-button" id="film-output">Open live output ↗</button></div><div class="film-pipeline"></div><div class="film-deliverables"><div><span class="eyebrow">YOUR CURRENT OUTPUT</span><h3></h3><p></p><button class="outline-button">Export this evidence ↓</button></div><details><summary>Inspect the current cue and evidence</summary><pre></pre></details></div><div class="film-requirements"><article><span class="eyebrow">SYNTHETIC FOOTBALL DATA</span><h3>Need the full-match pipeline?</h3><p>Choose “Synthetic match / data replay” above for coordinate-based passing, tracking, player focus and correction tests. Run a seeded 90-minute fixture through Azure for live events and a full-time AI recap.</p><button class="outline-button" id="film-full-match">Run the full-match generator ↗</button></article><article><span class="eyebrow">WHAT IS VERIFIED</span><h3>Evidence before spectacle.</h3><p>The film uses reviewed observations. Synthetic scenarios provide computed measurements. Three presenters use Azure AI; Vector calculates and Check applies evidence rules. All five have distinct public roles.</p><p>Truth Lab also checks actual frames with Azure vision; candidates remain unverified. Continuous player tracking, calibrated pixel measurements, Fabric integration and a rendering-partner connection are not implemented.</p></article></div>';
const stages=[['01','Ingest','Reviewed film markers enter as the playhead reaches them.'],['02','Interpret','Source and timestamp stay attached to every observation.'],['03','Explain','Observe → teach → calculate → challenge → synthesize.'],['04','Render','Azure streams expiring cues to a separate browser or OBS.'],['05','Personalize','Fan, beginner, math, tactical and player views. Three languages.']];
for(const [num,title,body]of stages){const card=el('article');card.append(el('span','',num),el('h3','',title),el('p','',body));inside.querySelector('.film-pipeline').append(card);}
document.getElementById('film-output').onclick=createBroadcastOutput();document.getElementById('film-full-match').onclick=()=>document.getElementById('lab-nav').click();inside.querySelector('.film-deliverables button').onclick=()=>download(pitchsideExport(input(matchSession.get())));
let lastKey='';
function render(s,source){
 for(const [section,{view,legacy}]of views){view.hidden=s.source!=='pitchside';legacy.hidden=s.source==='pitchside';const video=view.querySelector('video');if(video){if(s.section!==section||source!=='study-video')video.pause();if(source!=='study-video'&&video.readyState>=1&&Math.abs(video.currentTime-s.clipTime)>.2)video.currentTime=s.clipTime;}}
 if(s.source!=='pitchside'||!views.has(s.section))return;
 const p=pitchsideStory(input(s)),c=copy[s.language],{view}=views.get(s.section),key=[s.section,p.evidence.length,Math.floor(s.clipTime),s.language,s.mode,s.clipChallenge].join(':');if(key===lastKey)return;lastKey=key;
 if(s.section==='inside'){view.querySelector('.film-deliverables h3').textContent=p.title;view.querySelector('.film-deliverables p').textContent=p.body;view.querySelector('pre').textContent=JSON.stringify(pitchsideExport(input(s)),null,2);return;}
 view.querySelector('.study-label strong').textContent=c.film;view.querySelector('.study-label time').textContent=clipClock(s.clipTime)+' / '+clipClock(PITCHSIDE.duration);
 view.querySelector('.study-caption .eyebrow').textContent=c.observed;view.querySelector('.study-caption h2').textContent=p.title;view.querySelector('.study-caption p').textContent=p.body;
 view.querySelector('aside>.eyebrow').textContent=c.evidence+' '+p.clock;view.querySelector('aside>h3').textContent=s.section==='truth'?'The claim. The record.':p.evidence.length+' reviewed moments';view.querySelector('aside>button').textContent=c.replay;
 const list=view.querySelector('.film-evidence-list');list.replaceChildren();for(const e of p.evidence.slice(-4).reverse()){const button=el('button','film-evidence-item');button.append(el('time','',clipClock(e.second)+' ↗'),el('strong','',e.title),el('span','',e.observation));button.onclick=()=>matchSession.set({clipTime:e.second},'film-evidence');list.append(button);}if(!p.evidence.length)list.append(el('p','',p.copy.intro));
 const bottom=view.querySelector('.film-study-bottom');bottom.replaceChildren();
 if(s.section==='centre'){
  for(const mode of ['beginner','math','analyst']){const story=pitchsideStory({...input(s),mode}),card=el('article','film-lens');card.append(el('span','eyebrow',c[mode]),el('h3','',story.title),el('p','',story.body));if(mode==='math')card.append(el('code','',story.equation));bottom.append(card);}
 }else{
  const story=el('article','film-claim-story'),fact=el('article','film-claim-facts'),button=el('button','red-button',s.clipChallenge?c.restore:c.challenge);button.onclick=()=>matchSession.set({clipChallenge:!s.clipChallenge});story.append(el('span','eyebrow','R'+p.revision+' / EDITORIAL REVIEW'),el('h2','',s.clipChallenge?c.after:c.before),el('p','',c.question),el('blockquote','',c.claim),button);fact.append(el('span','eyebrow',c.verdict),el('h3','','v = d ÷ t'),el('p','',c.reason),el('code','',p.equation),el('p','',c.source));bottom.append(story,fact);
 }
 const exportButton=el('button','outline-button film-export',c.export);exportButton.onclick=()=>download(pitchsideExport(input(s)));bottom.after(exportButton);for(const old of [...view.querySelectorAll('.film-export')].slice(0,-1))old.remove();
}
addVisionCheck(views.get('truth').view);
matchSession.subscribe(render);render(matchSession.get());
